// Yutu the Jade Rabbit — Rive edition (magical-girl sidekick: tiny winged bunny with a star wand and her jade mortar).
// She is a Rive animation (yutu.riv, embedded below) driven by its state machine "Yutu".
// Her view model takes: mood (0 calm, 1 worried, 2 party, 3 sleepy), lookX / lookY
// (where her face turns, in px) and one trigger per reaction. The art, faces, effects
// and motion all live in the .riv; this file only tells her what is going on.
//   yutuSVG(mood, opts)  → HTML for a Yutu canvas (name kept for compatibility)
//   initYutu({ say })    → attaches Rive to every Yutu canvas + pointer/idle/petting behaviour
//   yutuReact(kind)      → plays a reaction: hello, pet, giggle, expense, over,
//                          income, saving, party, deleted, peek, yawn, wake

const YUTU_RIV = '';
// accessory slots in the .riv (view model numbers); these are her defaults
const YUTU_OUTFIT = { hat: 1, neck: 1, eyewear: 0 };
const MOOD_NUM = { calm: 0, happy: 0, worried: 1, party: 2, sleepy: 3 };
const RIGS = new Map(); // canvas → { r, vm, loaded }
let rivBytes = null;
const rivBuffer = () => {
  if (!rivBytes) rivBytes = Uint8Array.from(atob(YUTU_RIV), ch => ch.charCodeAt(0));
  return rivBytes.slice().buffer;
};
const sprites = () => [...document.querySelectorAll('canvas.yutu-rive')];
const live = () => sprites().filter(c => c.classList.contains('interactive'));
const calm = () => document.documentElement.classList.contains('reduce-motion') || matchMedia('(prefers-reduced-motion: reduce)').matches;
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
let dozing = false;

/* ---------------- Rive rigs ---------------- */
function vmSet(rig, name, value) {
  try { const p = rig.vm?.number(name); if (p) p.value = value; } catch (e) { /* older runtime */ }
}
function vmFire(rig, name) {
  try { rig.vm?.trigger(name)?.trigger(); } catch (e) { /* older runtime */ }
}
function moodOf(cv) {
  if (dozing && cv.classList.contains('interactive')) return 3;
  return MOOD_NUM[cv.dataset.mood] ?? 0;
}
function syncMotion(rig) {
  if (!rig.loaded) return;
  if (calm()) { if (rig.r.isPlaying) rig.r.pause(); }
  else if (!rig.r.isPlaying) rig.r.play();
}
function attach(cv) {
  if (RIGS.has(cv) || !window.rive) return;
  const rig = { r: null, vm: null, loaded: false };
  RIGS.set(cv, rig);
  rig.r = new rive.Rive({
    buffer: rivBuffer(),
    canvas: cv,
    stateMachines: 'Yutu',
    autoplay: true,
    autoBind: true,
    layout: new rive.Layout({ fit: rive.Fit.Contain, alignment: rive.Alignment.Center }),
    onLoad: () => {
      rig.loaded = true;
      rig.vm = rig.r.viewModelInstance;
      rig.r.resizeDrawingSurfaceToCanvas();
      vmSet(rig, 'mood', moodOf(cv));
      for (const [slot, n] of Object.entries(YUTU_OUTFIT)) vmSet(rig, slot, n);
      // under reduced motion she shows one still frame of her mood
      if (calm()) setTimeout(() => syncMotion(rig), 120);
    },
  });
}
function detach(cv) {
  const rig = RIGS.get(cv); if (!rig) return;
  RIGS.delete(cv);
  try { rig.r.cleanup(); } catch (e) { /* already gone */ }
}
function scan() {
  sprites().forEach(attach);
  for (const cv of RIGS.keys()) if (!cv.isConnected) detach(cv);
}
const liveRigs = () => live().map(cv => RIGS.get(cv)).filter(r => r && r.loaded);

/* ---------------- reactions ---------------- */
let sayHook = null, busyUntil = 0;
const REACTIONS = {
  hello:   { ms: 1900, say: ['Hi hi! ☾ Ready to count some coins?', 'Welcome back! I missed you (◕‿◕)♡'] },
  pet:     { ms: 1200, say: ['Hehe, that tickles! (≧▽≦)', '*happy bunny noises* ✿', 'More pets = more savings, right? ♡♡', 'You’re doing great with your money ✧', 'Boop! (｡•ᴗ•｡)'] },
  giggle:  { ms: 1300, say: ['Okay okay, I’m dizzy now! (@_@)♡'] },
  expense: { ms: 1000 },
  over:    { ms: 1500 },
  income:  { ms: 3600 },
  saving:  { ms: 2700 },
  party:   { ms: 2400 },
  deleted: { ms: 1000 },
  peek:    { ms: 900 },
  yawn:    { ms: 1600 },
  wake:    { ms: 900, say: ['Oh! I wasn’t sleeping, I was… budgeting (⊙_⊙;)'] },
};

export function yutuReact(kind, { say, soft = false } = {}) {
  const r = REACTIONS[kind]; if (!r) return;
  const now = performance.now();
  if (soft && now < busyUntil) return;
  busyUntil = now + r.ms;
  if (!calm()) liveRigs().forEach(rig => vmFire(rig, kind));
  const line = say || (r.say && r.say[Math.floor(Math.random() * r.say.length)]);
  if (line && sayHook) sayHook(line);
}

// change what Yutu wears on every Yutu canvas; pass only the slots to change
export function yutuDress(outfit = {}) {
  for (const slot of Object.keys(YUTU_OUTFIT)) {
    const n = Math.round(+outfit[slot]);
    if (slot in outfit && n >= 0 && n <= 3) YUTU_OUTFIT[slot] = n;
  }
  RIGS.forEach(rig => { if (rig.loaded) for (const [slot, n] of Object.entries(YUTU_OUTFIT)) vmSet(rig, slot, n); });
  return { ...YUTU_OUTFIT };
}

/* ---------------- markup ---------------- */
export function yutuSVG(mood = 'calm', { mini = false, interactive = false, title = 'Yutu the Jade Rabbit' } = {}) {
  const label = `${title}, ${{ calm: 'smiling', happy: 'smiling', worried: 'looking worried', party: 'celebrating', sleepy: 'dozing' }[mood] || 'smiling'}`;
  const role = interactive ? `role="button" tabindex="0" aria-label="${label}. Tap to pet her."` : `role="img" aria-label="${label}"`;
  return `<canvas class="yutu-rive${mini ? ' mini' : ''}${interactive ? ' interactive' : ''}" width="500" height="500" data-mood="${mood}" ${role}></canvas>`;
}

/* ---------------- behaviour ---------------- */
let started = false;
export function initYutu({ say } = {}) {
  sayHook = say || null;
  if (started) return; started = true;

  // attach to Yutus as the app renders them, let go of the ones it removes
  scan();
  new MutationObserver(scan).observe(document.body, { childList: true, subtree: true });
  const resizeAll = () => RIGS.forEach(rig => { if (rig.loaded) rig.r.resizeDrawingSurfaceToCanvas(); });
  addEventListener('resize', resizeAll);
  // reduced motion can be switched in settings at any time
  setInterval(() => RIGS.forEach(syncMotion), 1000);

  let lastMove = performance.now();
  const look = (cx, cy) => live().forEach(cv => {
    const rig = RIGS.get(cv); if (!rig?.loaded) return;
    const r = cv.getBoundingClientRect();
    if (!r.width) return;
    const dx = cx - (r.left + r.width / 2), dy = cy - (r.top + r.height * .5);
    vmSet(rig, 'lookX', clamp(dx / (r.width * .8), -1, 1) * 9);
    vmSet(rig, 'lookY', clamp(dy / (r.height * .8), -1, 1) * 6);
  });
  const setDozing = on => {
    dozing = on;
    live().forEach(cv => { const rig = RIGS.get(cv); if (rig?.loaded) vmSet(rig, 'mood', moodOf(cv)); });
  };
  const activity = () => {
    lastMove = performance.now();
    if (dozing) { setDozing(false); yutuReact('wake'); }
  };
  document.addEventListener('pointermove', e => { activity(); look(e.clientX, e.clientY); }, { passive: true });
  document.addEventListener('keydown', activity);
  document.addEventListener('focusin', e => { activity(); const r = e.target.getBoundingClientRect?.(); if (r && r.width) look(r.left + r.width / 2, r.top + r.height / 2); });
  document.addEventListener('pointerover', e => { if (e.target.closest?.('.fab') && !e.relatedTarget?.closest?.('.fab')) yutuReact('peek', { soft: true }); });
  setInterval(() => {
    if (dozing || performance.now() - lastMove < 30000) return;
    if (!live().some(cv => cv.dataset.mood !== 'sleepy')) return;
    dozing = true; yutuReact('yawn');
    setTimeout(() => { if (dozing) setDozing(true); }, 1600);
  }, 5000);

  let pets = [];
  const pet = () => {
    pets = pets.filter(t => Date.now() - t < 2500); pets.push(Date.now());
    yutuReact(pets.length >= 5 ? 'giggle' : 'pet');
    if (pets.length >= 5) pets = [];
  };
  document.addEventListener('click', e => { const c = e.target.closest?.('canvas.yutu-rive.interactive'); if (c) { if (e.detail) c.blur(); pet(); } });
  document.addEventListener('keydown', e => {
    const c = e.target.closest?.('canvas.yutu-rive.interactive');
    if (c && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); pet(); }
  });
}

// for tests/tools: a canvas's Rive rig ({ r, vm, loaded })
export const __yutuState = cv => RIGS.get(cv);

